import{_ as r,o as t,c as n,ae as a}from"./chunks/framework.BvHJbMD4.js";const c=JSON.parse('{"title":"Recherche: Der Kaufvertrag Horten-Alsberg (Duisburg 1936)","description":"","frontmatter":{},"headers":[],"relativePath":"recherche/der-kaufvertrag-horten-alsberg.md","filePath":"recherche/der-kaufvertrag-horten-alsberg.md"}'),i={name:"recherche/der-kaufvertrag-horten-alsberg.md"};function s(u,e,o,l,d,h){return t(),n("div",null,[...e[0]||(e[0]=[a('<h1 id="recherche-der-kaufvertrag-horten-alsberg-duisburg-1936" tabindex="-1">Recherche: Der Kaufvertrag Horten-Alsberg (Duisburg 1936) <a class="header-anchor" href="#recherche-der-kaufvertrag-horten-alsberg-duisburg-1936" aria-label="Permalink to &quot;Recherche: Der Kaufvertrag Horten-Alsberg (Duisburg 1936)&quot;">​</a></h1><p><strong>Das Fundament eines Imperiums auf den Trümmern einer Existenz.</strong></p><p>In der Geschichte der „Arisierung“ gilt die Übernahme des Kaufhauses <strong>Gebrüder Alsberg</strong> in Duisburg durch den damals erst 26-jährigen Helmut Horten als der entscheidende Moment, der seinen Aufstieg zum Kaufhauskönig ermöglichte. Für unser Mockumentary-Projekt ist dieser Vertrag das „Rauchschwert“ der historischen Beweisführung.</p><hr><h2 id="die-fakten-zum-vertrag" tabindex="-1">Die Fakten zum Vertrag <a class="header-anchor" href="#die-fakten-zum-vertrag" aria-label="Permalink to &quot;Die Fakten zum Vertrag&quot;">​</a></h2><h3 id="_1-datum-und-ort" tabindex="-1">1. Datum und Ort <a class="header-anchor" href="#_1-datum-und-ort" aria-label="Permalink to &quot;1. Datum und Ort&quot;">​</a></h3><ul><li><strong>Datum des Kaufvertrags:</strong> 23. April 1936</li><li><strong>Wirkungsdatum (Besitzwechsel):</strong> 1. Mai 1936</li><li><strong>Ort:</strong> Duisburg</li></ul><h3 id="_2-die-vertragsparteien" tabindex="-1">2. Die Vertragsparteien <a class="header-anchor" href="#_2-die-vertragsparteien" aria-label="Permalink to &quot;2. Die Vertragsparteien&quot;">​</a></h3><ul><li><strong>Käufer:</strong> Die neu gegründete <strong>Helmut Horten KG</strong>. Helmut Horten war der alleinige persönlich haftende Gesellschafter. Finanziert wurde der Kauf maßgeblich durch Kredite der Commerz- und Privatbank.</li><li><strong>Verkäufer:</strong> Die jüdischen Inhaber der <strong>Gebrüder Alsberg OHG</strong> (Duisburger Filiale), namentlich <strong>Hermann Strauß</strong> sowie <strong>Ernst und Curt Lauter</strong>. (Amalie Lauter, eine weitere Teilhaberin, konnte nicht mehr fliehen und wurde später im Holocaust ermordet).</li></ul><h3 id="_3-kaufpreis-und-umfang" tabindex="-1">3. Kaufpreis und Umfang <a class="header-anchor" href="#_3-kaufpreis-und-umfang" aria-label="Permalink to &quot;3. Kaufpreis und Umfang&quot;">​</a></h3><p>Der Kaufpreis betrug laut späteren Rückerstattungsakten insgesamt <strong>672.963,65 Reichsmark (RM)</strong>.</p><ul><li>Der Großteil der Summe (fast 672.000 RM) entfiel auf das Warenlager.</li><li>Das Inventar und die Geschäftseinrichtung wurden mit einem Bruchteil ihres Wertes bewertet.</li><li>Kritiker und Historiker weisen darauf hin, dass der Preis unter dem Druck der systematischen Verdrängung jüdischer Unternehmer zustande kam. Horten zahlte zwar, aber er zahlte in einem Markt, in dem die Verkäufer keine Wahl hatten.</li></ul><hr><h2 id="historische-einordnung-„arisierung-oder-„faires-geschaft" tabindex="-1">Historische Einordnung: „Arisierung“ oder „faires Geschäft“? <a class="header-anchor" href="#historische-einordnung-„arisierung-oder-„faires-geschaft" aria-label="Permalink to &quot;Historische Einordnung: „Arisierung“ oder „faires Geschäft“?&quot;">​</a></h2><h3 id="das-hoeres-gutachten-2022" tabindex="-1">Das Hoeres-Gutachten (2022) <a class="header-anchor" href="#das-hoeres-gutachten-2022" aria-label="Permalink to &quot;Das Hoeres-Gutachten (2022)&quot;">​</a></h3><p>Ein im Auftrag der Horten-Stiftung erstelltes, umfassendes wissenschaftliches Gutachten des Historikers <strong>Prof. Dr. Peter Hoeres</strong> (Lehrstuhl für Neueste Geschichte, Universität Würzburg) kam im Jahr 2022 zu dem Schluss, dass Horten zwar „kein NS-Ideologe“ gewesen sei, aber zweifellos ein <strong>„opportunistischer Nutznießer“</strong> des Unrechtssystems.</p><h3 id="offizielle-dokumente-quellen-pdf-downloads" tabindex="-1">Offizielle Dokumente &amp; Quellen (PDF-Downloads) <a class="header-anchor" href="#offizielle-dokumente-quellen-pdf-downloads" aria-label="Permalink to &quot;Offizielle Dokumente &amp; Quellen (PDF-Downloads)&quot;">​</a></h3><p>Für die historische Absicherung unseres Projekts stützen wir uns auf die offiziellen Veröffentlichungen der Helmut Horten Stiftung:</p><ul><li>📄 <strong><a href="https://www.helmut-horten-stiftung.org/fileadmin/user_upload/Gutachten_Horten_Hoeres_Kutzner.pdf" target="_blank" rel="noreferrer">Vollständiges Gutachten (PDF)</a></strong> – <em>„Über den Vermögens- und Geschäftsaufbau von Helmut Horten“</em> (Prof. Dr. Peter Hoeres &amp; Dr. Maximilian Kutzner).</li><li>📄 <strong><a href="https://www.helmut-horten-stiftung.org/fileadmin/user_upload/Zusammenfassung_Gutachten_Horten_Hoeres_Kutzner.pdf" target="_blank" rel="noreferrer">Zusammenfassung des Gutachtens (PDF)</a></strong> – Die wichtigsten Thesen auf einen Blick.</li><li>🌐 <strong><a href="https://www.helmut-horten-stiftung.org/" target="_blank" rel="noreferrer">Offizielle Website der Helmut Horten Stiftung</a></strong> – Historische Aufarbeitung des Erbes.</li></ul><h3 id="die-„arier-werbung" tabindex="-1">Die „Arier-Werbung“ <a class="header-anchor" href="#die-„arier-werbung" aria-label="Permalink to &quot;Die „Arier-Werbung“&quot;">​</a></h3><p>Das Gutachten belegt unter anderem, dass Horten unmittelbar nach der Übernahme am 1. Mai 1936 Anzeigen in der Lokalpresse (Duisburger General-Anzeiger) schaltete, in denen er offensiv mit dem <strong>„arischen Besitz“</strong> warb. Er nutzte die durch den NS-Staat geschaffenen Bedingungen der Ausgrenzung gezielt für seinen geschäftlichen Vorteil.</p><hr><h2 id="der-verbleib-des-originalvertrags" tabindex="-1">Der Verbleib des Originalvertrags <a class="header-anchor" href="#der-verbleib-des-originalvertrags" aria-label="Permalink to &quot;Der Verbleib des Originalvertrags&quot;">​</a></h2><p>Während viele Originaldokumente der 1930er Jahre im Krieg oder bei der Entnazifizierung verloren gingen, sind die Kerndaten des Duisburger Kaufs (Preis: 672.963,65 RM) durch die detaillierte Rekonstruktion im Hoeres-Gutachten sowie durch Rückerstattungsverfahren der Nachkriegszeit historisch beglaubigt.</p><h3 id="bedeutung-fur-das-drehbuch-teil-2-3" tabindex="-1">Bedeutung für das Drehbuch (Teil 2 &amp; 3) <a class="header-anchor" href="#bedeutung-fur-das-drehbuch-teil-2-3" aria-label="Permalink to &quot;Bedeutung für das Drehbuch (Teil 2 &amp; 3)&quot;">​</a></h3><p>Die im Gutachten beschriebene <strong>„Kühle des Geschäfts“</strong> ist der emotionale Anker unserer Mockumentary. Wir zeigen nicht den brutalen Schläger, sondern den effizienten Buchhalter des Unrechts – eine Darstellung, die durch die wissenschaftliche Forschung von Prof. Hoeres gestützt wird.</p><hr><p><em>Quelle: Gutachten über den Vermögens- und Geschäftsaufbau von Helmut Horten (2022), Helmut Horten Stiftung.</em></p>',28)])])}const f=r(i,[["render",s]]);export{c as __pageData,f as default};
